+++ b/mailnews/imap/public/nsIImapServerSink.idl
@@ -109,8 +109,10 @@ interface nsIImapServerSink : nsISupports {
    *
    * @param aServerString  The string to alert the user with.
    * @param url            The running url.
+   * @param forBye         Print the whole server response when greeting is BYE.
    */
-  void fEAlertFromServer(in ACString aServerString, in nsIMsgMailNewsUrl aUrl);
+  void fEAlertFromServer(in ACString aServerString, in nsIMsgMailNewsUrl aUrl,
+                         in boolean forBye);

   /**
    * Alerts the user with a certificate error.
diff --git a/mailnews/imap/src/nsImapIncomingServer.cpp b/mailnews/imap/src/nsImapIncomingServer.cpp
index 85f3e048fcc..9d0de0dc620 100644
--- a/mailnews/imap/src/nsImapIncomingServer.cpp
+++ b/mailnews/imap/src/nsImapIncomingServer.cpp
@@ -1759,24 +1759,32 @@ nsImapIncomingServer::FEAlertWithName(const char* aMsgName,
 }

 NS_IMETHODIMP nsImapIncomingServer::FEAlertFromServer(
-    const nsACString& aServerString, nsIMsgMailNewsUrl* aUrl) {
+    const nsACString& aServerString, nsIMsgMailNewsUrl* aUrl, bool forBye) {
   NS_ENSURE_TRUE(!aServerString.IsEmpty(), NS_OK);

   nsCString message(aServerString);
   message.Trim(" \t\b\r\n");
   NS_ENSURE_TRUE(!message.IsEmpty(), NS_OK);
-  if (message.Last() != '.') message.Append('.');

-  // Skip over the first two words (the command tag and "NO").
-  // Find the first word break.
-  int32_t pos = message.FindChar(' ');
+  // Ensure a period at end and skip over the first two words (the command tag
+  // and "NO"). But keep it all as-is if this is for an untagged BYE which can
+  // occur in place of a correct greeting response while imap server connection
+  // is is attempting to be made; e.g., print "* BYE no can do" in the alert.
+  if (!forBye) {
+    if (message.Last() != '.') message.Append('.');

-  // Find the second word break.
-  if (pos != -1) pos = message.FindChar(' ', pos + 1);
+    // Find the first word break.
+    int32_t pos = message.FindChar(' ');

-  // Adjust the message.
-  if (pos != -1) message = Substring(message, pos + 1);
+    // Find the second word break.
+    if (pos != -1) pos = message.FindChar(' ', pos + 1);

+    // Adjust the message.
+    if (pos != -1) message = Substring(message, pos + 1);
+  } else {
+    // For untagged BYE greeting show the string on a new line.
+    message.Insert("\r\n", 0);
+  }
   nsAutoCString hostName;
   GetPrettyName(hostName);

diff --git a/mailnews/imap/src/nsImapProtocol.cpp b/mailnews/imap/src/nsImapProtocol.cpp
index ea574af9fe6..a5f59e3fffb 100644
--- a/mailnews/imap/src/nsImapProtocol.cpp
+++ b/mailnews/imap/src/nsImapProtocol.cpp
@@ -1627,6 +1627,8 @@ void nsImapProtocol::EstablishServerConnection() {
 #define ESC_CAPABILITY_OK_LEN ESC_LENGTH(ESC_CAPABILITY_OK)
 #define ESC_CAPABILITY_GREETING (ESC_CAPABILITY_OK "CAPABILITY")
 #define ESC_CAPABILITY_GREETING_LEN ESC_LENGTH(ESC_CAPABILITY_GREETING)
+#define ESC_BYE "* BYE"
+#define ESC_BYE_LEN ESC_LENGTH(ESC_BYE)

   char* serverResponse = CreateNewLineFromSocket();  // read in the greeting
   // record the fact that we've received a greeting for this connection so we
@@ -1698,8 +1700,21 @@ void nsImapProtocol::EstablishServerConnection() {
            hostName.get()));
       SetConnectionStatus(NS_ERROR_FAILURE);  // stop netlib
     }
+  } else if (!PL_strncasecmp(serverResponse, ESC_BYE, ESC_BYE_LEN)) {
+    if (m_imapServerSink) {
+      nsCOMPtr<nsIMsgMailNewsUrl> mailnewsUrl = do_QueryInterface(m_runningUrl);
+      m_imapServerSink->FEAlertFromServer(nsDependentCString(serverResponse),
+                                          mailnewsUrl, true);
+    }
+    SetConnectionStatus(NS_ERROR_FAILURE);  // stop netlib
+    if (MOZ_LOG_TEST(IMAP, LogLevel::Error)) {
+      const nsCString& hostName = GetImapHostName();
+      MOZ_LOG(IMAP, LogLevel::Error,
+              ("BYE greeting sent by IMAP server %s. "
+               "Connection rejected by server and is now closed.",
+               hostName.get()));
+    }
   }
-
   PR_Free(serverResponse);  // we don't care about the greeting yet...

 #undef ESC_LENGTH
@@ -1713,6 +1728,8 @@ void nsImapProtocol::EstablishServerConnection() {
 #undef ESC_CAPABILITY_OK_LEN
 #undef ESC_CAPABILITY_GREETING
 #undef ESC_CAPABILITY_GREETING_LEN
+#undef ESC_BYE
+#undef ESC_BYE_LEN
 }

 // This can get called from the UI thread or an imap thread.
@@ -5232,11 +5249,11 @@ void nsImapProtocol::AlertUserEventFromServer(const char* aServerEvent,
       nsCOMPtr<nsIMsgMailNewsUrl> mailnewsUrl =
           do_QueryInterface(m_runningUrlLatest);
       m_imapServerSinkLatest->FEAlertFromServer(
-          nsDependentCString(aServerEvent), mailnewsUrl);
+          nsDependentCString(aServerEvent), mailnewsUrl, false);
     } else if (m_imapServerSink) {
       nsCOMPtr<nsIMsgMailNewsUrl> mailnewsUrl = do_QueryInterface(m_runningUrl);
       m_imapServerSink->FEAlertFromServer(nsDependentCString(aServerEvent),
-                                          mailnewsUrl);
+                                          mailnewsUrl, false);
     }
   }
 }
